import json
from collections import defaultdict

tax=json.load(open('data/taxonomy.json',encoding='utf-8'))

# build path map by key
nodes=[]
def walk(node,parent=None):
    nodes.append((node,parent))
    for ch in node.get('children',[]) or []:
        walk(ch,node)
for r in tax.get('roots',[]):
    walk(r,None)

# helper
children=defaultdict(list)
labels={}
parent={}
for n,p in nodes:
    k=n.get('key');
    if not k: continue
    labels[k]=n.get('label')
    if p and p.get('key'):
        parent[k]=p.get('key')
        children[p.get('key')].append(k)

need=['kinh-nghiem-hoi-dap-nghe-nghiep','thu-tuc-doanh-nghiep','luat-bo-luat','lao-dong-tien-luong','gtgt-hoa-don','tai-khoan-hach-toan','nghi-quyet-quyet-dinh','mau-bieu-doanh-nghiep-thu-tuc','htkk-etax-thue-dien-tu','cong-van']
for lv2 in need:
    print('\n===',lv2,labels.get(lv2),'===')
    lv3s=children.get(lv2,[])
    if not lv3s:
        print(' (no direct lv3)')
        continue
    for k in lv3s:
        print('-',k,'|',labels.get(k))
