import json, unicodedata
from collections import Counter

def norm(s):
  s=(s or '').lower();
  s=''.join(ch for ch in unicodedata.normalize('NFD',s) if unicodedata.category(ch)!='Mn')
  return s.replace('đ','d').strip()

def is_job(t):
  return ('tuyen' in t) or ('thuc tap' in t)

def is_course(t):
  return t.startswith('khoa hoc') or t.startswith('lop hoc')

def map_row(a):
  t=norm(a.get('title') or '')
  lv1=a.get('topicLv1Key') or ''
  lv2=a.get('topicLv2Key') or ''
  reason='keep'
  if is_job(t):
